INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Programmiersprachen mit unterschiedlichen Paradigmen dieselben Probleme gleich effizient lösen?', 2, '[{"text": "Nein", "correct": true, "because": "Paradigmen beeinflussen Effizienz je nach Problem"}, {"text": "Ja", "correct": false, "because": "Unterschiede wirken sich aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Syntax einer Programmiersprache unabhängig von ihrer Semantik?', 2, '[{"text": "Nein", "correct": true, "because": "Syntax bestimmt, wie Semantik ausgedrückt wird"}, {"text": "Ja", "correct": false, "because": "Beides ist verknüpft"}]'),
('00000000-0000-0000-0000-000000000000', 'Können alle Programmiersprachen gleich gut für systemnahe Programmierung verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Systemnähe hängt von Sprache ab"}, {"text": "Ja", "correct": false, "because": "Sprachen wie C sind spezialisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind interpretierte Programmiersprachen immer langsamer als kompilierte?', 2, '[{"text": "Nein", "correct": true, "because": "Optimierungen können Unterschiede verringern"}, {"text": "Ja", "correct": false, "because": "Nicht absolut"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Programmiersprache ohne objektorientierte Features moderne Anwendungen unterstützen?', 2, '[{"text": "Ja", "correct": true, "because": "Funktionale oder prozedurale Ansätze möglich"}, {"text": "Nein", "correct": false, "because": "OO ist nicht zwingend"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Unterschied besteht zwischen C und Python in Bezug auf die Ausführung?', 2, '[{"text": "C wird kompiliert, Python interpretiert", "correct": true, "because": "C erzeugt Maschinencode, Python läuft zur Laufzeit"}, {"text": "Beide werden interpretiert", "correct": false, "because": "C ist kompiliert"}, {"text": "Beide werden kompiliert", "correct": false, "because": "Python ist interpretiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprache unterscheidet sich durch starke Typisierung von anderen?', 3, '[{"text": "Java", "correct": true, "because": "Strikte Typprüfung zur Compile-Zeit"}, {"text": "Python", "correct": false, "because": "Dynamische Typisierung"}, {"text": "JavaScript", "correct": false, "because": "Lose Typisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Unterschied prägt die Verwendung von Assembly im Vergleich zu Hochsprachen?', 2, '[{"text": "Direkte Hardwaresteuerung", "correct": true, "because": "Assembly ist maschinnah"}, {"text": "Hohe Lesbarkeit", "correct": false, "because": "Assembly ist kryptisch"}, {"text": "Automatische Speicherverwaltung", "correct": false, "because": "Fehlt in Assembly"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprache unterscheidet sich durch ihren funktionalen Ansatz von objektorientierten Sprachen?', 2, '[{"text": "Haskell", "correct": true, "because": "Rein funktional"}, {"text": "C++", "correct": false, "because": "Objektorientiert"}, {"text": "Ruby", "correct": false, "because": "Objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Unterschied zwischen PHP und C# beeinflusst die Webentwicklung?', 2, '[{"text": "PHP ist serverseitig interpretiert, C# kompiliert", "correct": true, "because": "PHP direkt ausführbar, C# braucht Compilation"}, {"text": "Beide sind gleich schnell", "correct": false, "because": "Ausführungsunterschiede"}, {"text": "C# ist skriptbasiert", "correct": false, "because": "C# ist kompiliert"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zwischen kompilierten und interpretierten Sprachen?', 4, '[{"text": "Kompilierte sind schneller ausgeführt", "correct": true, "because": "Maschinencode optimiert"}, {"text": "Interpretierte brauchen keinen Compiler", "correct": true, "because": "Laufzeitumgebung reicht"}, {"text": "Kompilierte sind immer plattformunabhängig", "correct": false, "because": "Plattformabhängig"}, {"text": "Interpretierte bieten direkte Fehlerkorrektur", "correct": true, "because": "Sofortige Ausführung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale unterscheiden objektorientierte von funktionalen Sprachen?', 3, '[{"text": "OO nutzt Klassen und Objekte", "correct": true, "because": "Kernprinzip der OO"}, {"text": "Funktionale vermeiden Zustandsänderungen", "correct": true, "because": "Rein funktional"}, {"text": "OO ist immer langsamer", "correct": false, "because": "Geschwindigkeit variiert"}, {"text": "Funktionale nutzen Vererbung", "correct": false, "because": "OO-Merkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede beeinflussen die Wahl zwischen Python und Java?', 3, '[{"text": "Typisierung: dynamisch vs. statisch", "correct": true, "because": "Python dynamisch, Java statisch"}, {"text": "Ausführung: interpretiert vs. kompiliert", "correct": true, "because": "Python interpretiert, Java kompiliert"}, {"text": "Syntaxkomplexität: einfach vs. komplex", "correct": true, "because": "Python simpler"}, {"text": "Speicherverwaltung: identisch", "correct": false, "because": "Java mit Garbage Collector"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zwischen C und C++?', 4, '[{"text": "C++ unterstützt Objektorientierung", "correct": true, "because": "Klassen und Objekte"}, {"text": "C ist prozedural", "correct": true, "because": "Keine OO-Features"}, {"text": "C++ hat keine Pointer", "correct": false, "because": "Pointer vorhanden"}, {"text": "C++ bietet STL", "correct": true, "because": "Standard Template Library"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede prägen Hochsprachen vs. Maschinensprachen?', 3, '[{"text": "Abstraktion: hoch vs. niedrig", "correct": true, "because": "Hochsprachen abstrahieren"}, {"text": "Lesbarkeit: leicht vs. schwer", "correct": true, "because": "Hochsprachen lesbarer"}, {"text": "Ausführungsgeschwindigkeit: gleich", "correct": false, "because": "Maschinensprache schneller"}, {"text": "Hardwarezugriff: indirekt vs. direkt", "correct": true, "because": "Maschinensprache näher"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Python und Java unterscheiden sich nur in der Syntax. b) C ist für systemnahe Programmierung besser geeignet als Python.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Unterschiede umfassender, C maschinnah"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Interpretierte Sprachen sind plattformunabhängig. b) Objektorientierte Sprachen sind immer kompiliert.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Plattform hängt von Interpreter ab, OO auch interpretiert"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) C++ unterscheidet sich von C durch OO-Features. b) Funktionale Sprachen sind für GUI-Entwicklung ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "C++ erweitert C, funktional flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Java und JavaScript unterscheiden sich nur im Namen. b) Assembly ist schneller als Hochsprachen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Java und JS unterschiedlich, Assembly maschinnah"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Dynamische Typisierung erhöht die Laufzeitflexibilität. b) Kompilierte Sprachen sind immer schwerer zu debuggen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dynamisch flexibel, Debugging variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

